// GENERATED by tools/sync.py from plant-controller2/src/deviceInfo.h - do not edit, change the original project instead.
// Lets the companion app (and any mDNS browser) find this controller, at home
// on the wifi network as well as in soft-AP mode (192.168.4.1).
//   GET /info  -> {"type":"greenhouse","name":"Greenhouse","id":"a1b2c3","version":"2.0","mode":"sta"|"ap","ip":"..."}
//   mDNS       -> greenhouse-<id>.local, service _espdevice._tcp (TXT type, id, name)

#define DEVICE_TYPE "greenhouse"
#define DEVICE_NAME "Greenhouse"
#define FIRMWARE_VERSION "2.0"

String deviceId(){
  uint8_t mac[6];
  esp_read_mac(mac, ESP_MAC_WIFI_STA); // same id in station and soft-AP mode
  char id[7];
  snprintf(id, sizeof(id), "%02x%02x%02x", mac[3], mac[4], mac[5]);
  return String(id);
}

void onInfoRequest(AsyncWebServerRequest *request){
  String ip = wifiStationMode ? WiFi.localIP().toString() : WiFi.softAPIP().toString();
  String json = String("{\"type\":\"") + DEVICE_TYPE + "\",\"name\":\"" + DEVICE_NAME + "\",\"id\":\"" + deviceId()
              + "\",\"version\":\"" + FIRMWARE_VERSION + "\",\"mode\":\"" + (wifiStationMode ? "sta" : "ap")
              + "\",\"ip\":\"" + ip + "\",\"modes\":" + modeListJson() + "}";
  AsyncWebServerResponse *response = request->beginResponse(200, "application/json", json);
  response->addHeader("Access-Control-Allow-Origin", "*");
  request->send(response);
}

void setupDiscovery(){
  String id = deviceId();
  String host = String(DEVICE_TYPE) + "-" + id;
  if (MDNS.begin(host.c_str())){
    MDNS.addService("http", "tcp", 80);
    MDNS.addService("espdevice", "tcp", 80);
    MDNS.addServiceTxt("espdevice", "tcp", "type", DEVICE_TYPE);
    MDNS.addServiceTxt("espdevice", "tcp", "id", id.c_str());
    MDNS.addServiceTxt("espdevice", "tcp", "name", DEVICE_NAME);
  }
}
